package com.ethk3.novaonepro.r952;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.os.CancellationSignal;import android.os.OperationCanceledException;import com.ethk3.novaonepro.*;import java.util.*;
import static com.ethk3.novaonepro.ResearchVisualDataR82.*;
/** Exact retained data, bounded read worker only; never creates missing history or qualifications. */
public final class ResearchVisualExtrasR82 {
 private ResearchVisualExtrasR82(){}
 public static List<Panel> load(SQLiteDatabase db,String asOf,CancellationSignal cancel){if(cancel==null)throw new IllegalArgumentException("CANCELLATION_REQUIRED");List<Panel> out=new ArrayList<>();try{draws(db,asOf,cancel,out);}catch(OperationCanceledException e){throw e;}catch(RuntimeException e){out.add(empty("deep","号码轨迹与分桶K线",e));}
  try{cancel.throwIfCanceled();LongSummaryBindingsR80.VisualR82 v=LongSummaryBindingsR80.visualR82(db,asOf,cancel);for(int window:LongScaleCountsR80.windows()){List<Point> cells=new ArrayList<>();int n=v.support(window);for(int p=1;p<=10;p++){long[] counts=v.counts(window,p);for(int d=0;d<10;d++)cells.add(new Point("位置"+p+"/号码"+(d+1),n==window?counts[d]/(double)n:Double.NaN,Double.NaN,Double.NaN,n,"count="+counts[d]+"; support="+n+"; protocol="+LongScaleSummaryR80.PROTOCOL+"; snapshot="+v.snapshotHash+"; receipt="+v.receiptHash));}out.add(new Panel("atoms",window+"期真实长周期频率","HEATMAP",LongScaleSummaryR80.SNAPSHOT,v.epoch+" / "+v.through,"每行位置、每列号码1至10。完整支持"+n+"/"+window+"；未满窗口留空。5000期原始滚动与43200期摘要独立，不重造已删除原始历史。",n==window?"OBSERVED":"WAIT_LONG_SCALE_HISTORY",cells,Collections.<Edge>emptyList()));}}catch(OperationCanceledException e){throw e;}catch(RuntimeException e){out.add(empty("atoms","长周期摘要",e));}
  try{atoms(db,asOf,cancel,out);}catch(OperationCanceledException e){throw e;}catch(RuntimeException e){out.add(empty("atoms","原子质量与在线网络",e));}return out;
 }
 private static Panel empty(String page,String title,RuntimeException e){return new Panel(page,title,"STATUS","","",e.getClass().getSimpleName()+":"+String.valueOf(e.getMessage()),"UNAVAILABLE",Collections.<Point>emptyList(),Collections.<Edge>emptyList());}
 private static void draws(SQLiteDatabase db,String asOf,CancellationSignal cancel,List<Panel> out){List<String> issues=new ArrayList<>();List<Integer> digits=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT issue,n1 FROM draws WHERE dirty=0 AND issue<=? ORDER BY issue DESC LIMIT 120",new String[]{asOf},cancel)){while(c.moveToNext()){cancel.throwIfCanceled();issues.add(c.getString(0));digits.add(c.isNull(1)?-1:c.getInt(1));}}Collections.reverse(issues);Collections.reverse(digits);List<Point> line=new ArrayList<>(),candles=new ArrayList<>();
  for(int i=0;i<issues.size();i++){cancel.throwIfCanceled();int d=digits.get(i);if(i>0&&TargetIssueResolver.distance(issues.get(i-1),issues.get(i))!=1)line.add(new Point("缺期",Double.NaN,Double.NaN,Double.NaN,0,"期号不连续，禁止插值"));line.add(new Point(issues.get(i),d>=1&&d<=10?d:Double.NaN,Double.NaN,Double.NaN,1,"位置=1；原始开奖数字，非价格或收益"));while(line.size()>120)line.remove(0);}
  for(int start=0;start<digits.size();start+=6){int end=Math.min(start+6,digits.size()),lo=11,hi=0;boolean known=true;for(int j=start;j<end;j++){int d=digits.get(j);known&=d>=1&&d<=10&&(j==start||TargetIssueResolver.distance(issues.get(j-1),issues.get(j))==1);lo=Math.min(lo,d);hi=Math.max(hi,d);}candles.add(new Point(issues.get(start)+"—"+issues.get(end-1),known?digits.get(end-1):Double.NaN,known?lo:Double.NaN,known?hi:Double.NaN,end-start,"6期分桶：O=首个号码 H=最大 L=最小 C=末个；桶内缺期整桶留空。非证券K线，不含价格/成交量。",known?digits.get(start):Double.NaN));}
  out.add(new Panel("deep","位置1真实号码轨迹","LINE","draws.dirty=0","最近最多120条 / <= "+asOf,"号码纵轴1至10，跨期缺口不连线；描述图形不证明可预测性。",line.isEmpty()?"NO_OBSERVATIONS":"OBSERVED",line,Collections.<Edge>emptyList()));out.add(new Panel("deep","6期号码分桶OHLC","CANDLE","draws.n1","最近最多120条 / <= "+asOf,"开奖数字描述统计，非价格/交易量/盈利。桶内样本数在详情核对。",candles.isEmpty()?"NO_OBSERVATIONS":"OBSERVED",candles,Collections.<Edge>emptyList()));
 }
 private static void atoms(SQLiteDatabase db,String asOf,CancellationSignal cancel,List<Panel> out){List<Point> quality=new ArrayList<>(),missing=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT atom_id,n,missing,gain_sum,gain_sq,state,last_issue,positive_blocks,blocks FROM "+AtomicToolWorldR943.QUALITY+" WHERE last_issue<=? ORDER BY atom_index LIMIT 241",new String[]{asOf},cancel)){while(c.moveToNext()){cancel.throwIfCanceled();if(quality.size()==240)throw new IllegalStateException("ATOM_CHART_BUDGET_EXCEEDED_USE_TEXT_PAGING");long n=c.getLong(1),m=c.getLong(2);if(n<0||m<0||n>Long.MAX_VALUE-m)throw new IllegalStateException("ATOM_COUNT_INVALID");double mean=n>0?c.getDouble(3)/n:Double.NaN,se=n>1?Math.sqrt(Math.max(0,c.getDouble(4)/n-mean*mean)/n):Double.NaN;String info="state="+c.getString(5)+"; through="+c.getString(6)+"; positive120Blocks="+c.getLong(7)+"/"+c.getLong(8)+"; missing="+m+"; present="+n;quality.add(new Point(c.getString(0),mean,n>1?mean-1.96*se:Double.NaN,n>1?mean+1.96*se:Double.NaN,n,info+"; 区间为原质量统计正态近似，序列相关不可当独立Future证书。"));missing.add(new Point(c.getString(0),n+m>0?m/(double)(n+m):Double.NaN,Double.NaN,Double.NaN,n+m,info));}}
  for(int i=0;i<quality.size();i+=120){int end=Math.min(i+120,quality.size());out.add(new Panel("atoms","原子Brier增益 "+(i/120+1),"BAR",AtomicToolWorldR943.QUALITY,"当前累积状态 / <= "+asOf,"只读当前原子描述统计，不将RESEARCH_PARENT当证书；分母/区间假设见详情。","OBSERVED",quality.subList(i,end),Collections.<Edge>emptyList()));out.add(new Panel("atoms","原子缺失率 "+(i/120+1),"BAR",AtomicToolWorldR943.QUALITY,"当前累积状态 / <= "+asOf,"分母=present+missing，无观测留空。","OBSERVED",missing.subList(i,end),Collections.<Edge>emptyList()));}
  List<Point> loss=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT target_issue,network_probability,hit,network_hash,trained_until,record_hash FROM "+AtomicToolWorldR943.CONTEXT+" WHERE hit IN(0,1) AND target_issue<=? ORDER BY target_issue DESC LIMIT 120",new String[]{asOf},cancel)){while(c.moveToNext()){cancel.throwIfCanceled();double p=c.isNull(1)?Double.NaN:c.getDouble(1);loss.add(new Point(c.getString(0),p>=0&&p<=1?Math.pow(p-c.getInt(2),2):Double.NaN,Double.NaN,Double.NaN,1,"frozen_probability="+p+"; hit="+c.getInt(2)+"; model="+c.getString(3)+"; trained_until="+c.getString(4)+"; receipt="+c.getString(5)));}}Collections.reverse(loss);out.add(new Panel("atoms","原子网络逐期Brier损失","BAR",AtomicToolWorldR943.CONTEXT,"最近最多120个已结算上下文 / <= "+asOf,"每柱为赛前输出和实际标签平方误差，保留模型hash；不把不同模型连成同一训练曲线，不授予资格。",loss.isEmpty()?"NO_OBSERVATIONS":"OBSERVED",loss,Collections.<Edge>emptyList()));
 }
}
